sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float shape;
uniform float2 center;
uniform float sizeX;
uniform float sizeY;
uniform float cornerRadius;
uniform float rotation;
uniform float feather;
uniform float invert;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 p = rot2(coord - ctr, -radians(rotation)) / (size * float2(sizeX, sizeY) * 0.5);
    float sd = length(p) - 1.0;
    if (shape > 0.5 && shape < 1.5) {
        sd = max(abs(p.x), abs(p.y)) - 1.0;
    } else if (shape > 1.5) {
        float rr = min(cornerRadius, 1.0);
        float2 q = abs(p) - float2(1.0 - rr);
        sd = length(max(q, float2(0.0))) + min(max(q.x, q.y), 0.0) - rr;
    }
    float m = 1.0 - smoothstep(-feather - 0.0001, 0.0, sd);
    if (invert > 0.5) m = 1.0 - m;
    return fin(c, c * m, opacity);
}
